/bin/bash -lc "which python3 && python3 - <<'PY'
try:
 import PyPDF2
 print('PyPDF2 available', PyPDF2.__version__)
except Exception as e:
 print('PyPDF2 unavailable:', e)
try:
 import pypdf
 print('pypdf available', pypdf.__version__)
except Exception as e:
 print('pypdf unavailable:', e)
PY"

