/bin/bash -lc "python3 - <<'PY'
for m in ['fitz','pikepdf','pdfrw']:
    try:
        mod=__import__(m)
        print(m, 'available', getattr(mod, '__version__', ''))
    except Exception as e:
        print(m, 'unavailable')
PY"

